/// Ensures one imported model generation needed by a focused authoring surface is
/// being materialized and returns it once the exact generation is resident.
///
/// This is the single-source counterpart of [`Self::prepare_scene`]. It keeps
/// document-dependent inspectors such as Animation Set Target Preview on the same
/// asynchronous residency path as Scene View instead of synchronously reparsing a
/// multi-skeleton source on the UI thread.
pub(crate) fn prepare_model_source(
    &self,
    source_id: &AssetId,
    entry: &engine::ManifestEntry,
    assets_root: &Path,
    priority: PreviewAssetPriority,
) -> Option<Arc<engine::GltfImportResult>> {
    let source_path = assets_root.join(&entry.path);
    if !engine::asset_path_matches_kind(engine::AssetKind::GltfSource, &source_path) {
        return None;
    }
    let dependencies = entry
        .import_settings
        .source_dependencies
        .iter()
        .map(|path| assets_root.join(path))
        .collect::<Vec<_>>();
    let current_stamp = SourceStamp::capture(&source_path, &dependencies).ok();
    if entry.import_settings.source_fingerprint.is_none()
        || entry
            .import_settings
            .source_stamp
            .as_ref()
            .is_some_and(|expected| current_stamp.as_ref() != Some(expected))
    {
        return None;
    }

    let skeleton_records = entry.import_settings.skeleton_records.clone();
    let contact_bones = entry.import_settings.contact_bones.clone();
    let request = SourceRequest {
        source_id: source_id.clone(),
        generation: SourceGeneration {
            source_path: source_path.clone(),
            source_stamp: current_stamp,
            source_fingerprint: entry.import_settings.source_fingerprint.clone(),
            settings_fingerprint: settings_fingerprint(&skeleton_records, &contact_bones),
        },
        skeleton_records: skeleton_records.clone(),
        contact_bones: contact_bones.clone(),
    };
    if matches!(
        self.prepare_source(request, priority),
        PreviewResidencyState::Failed(_)
    ) {
        return None;
    }
    self.launch_available();
    self.model_cache.lookup_source(
        source_id,
        &source_path,
        &skeleton_records,
        &contact_bones,
    )
}

